/**
 * Smoothly scrolls to an in-page anchor, routing through the Lenis instance
 * (exposed on `window.lenis` by LenisScroll) when it's available so the jump
 * matches the rest of the site's smooth-scroll feel.
 */
export const scrollToHash = (hash, offset = -100) => {
  if (!hash) return;
  const target = typeof hash === "string" ? document.querySelector(hash) : hash;
  if (!target) return;

  if (window.lenis && typeof window.lenis.scrollTo === "function") {
    window.lenis.scrollTo(target, { offset });
  } else {
    target.scrollIntoView({ behavior: "smooth" });
  }
};
